-- DISNEYHEROES-BM(~V7.5+)[X64]-V16.01
-- Do not edit this file. Any change breaks the decoder.
local _bgnrzg = 95
local _yncqxy = 165
local _mjmsxc = 130
local _rkrsvd = ""

local _rnlcbs = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _vmtcjt(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _mvwcos(d)
	d = d:gsub("[^" .. _rnlcbs .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_rnlcbs:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _iufbkc = _mvwcos(_rkrsvd)
local _ttcmlc = { _bgnrzg, _yncqxy, _mjmsxc }
local _bnbgzm = {}
for i = 1, #_iufbkc do
	_bnbgzm[i] = string.char(_vmtcjt(_iufbkc:byte(i), _ttcmlc[(i - 1) % 3 + 1]))
end

local _rfetoe = load or loadstring
local _rvajmb, _hfrjaz = _rfetoe(table.concat(_bnbgzm), "=w")
if not _rvajmb then
	gg.alert("Corrupted file: " .. tostring(_hfrjaz))
	os.exit()
end
_rvajmb()
